-- Original guestbook entries recovered from the pre-D1 mock data (git history), never seeded before
INSERT INTO guestbook_entries (id, name, location, message, created_at) VALUES (lower(hex(randomblob(16))), 'Lars', 'Notodden', 'Heard Muddy on the radio at 14. Never looked back. Thanks for keeping the flame alive.', '2026-04-30 09:00:00');
INSERT INTO guestbook_entries (id, name, location, message, created_at) VALUES (lower(hex(randomblob(16))), 'Marianne', NULL, 'Tok med datteren min på Mandal Blues for første gang i fjor — nå er hun frelst på 13 år. Bluesen lever videre.', '2026-04-18 09:00:00');
INSERT INTO guestbook_entries (id, name, location, message, created_at) VALUES (lower(hex(randomblob(16))), 'Tom', 'Hamburg', 'Found this site by accident, lost an entire afternoon in the artist profiles. Beautifully done.', '2026-04-02 09:00:00');
INSERT INTO guestbook_entries (id, name, location, message, created_at) VALUES (lower(hex(randomblob(16))), 'Anna', 'Bergen', 'Tusen takk for det norske perspektivet — sjelden å se Notodden nevnt i samme setning som Chess Records.', '2026-03-21 09:00:00');
-- 8 in-depth album reviews for /reviews, linked to existing artist profiles
-- (personal/enthusiast voice — see conversation for the rewrite pass)
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'muddy-waters-folk-singer', 'muddy-waters', 'Muddy Waters', 'Folk Singer', 1964, 'Chess Records', 'Delta Blues / Acoustic', 'https://upload.wikimedia.org/wikipedia/en/9/98/Muddywatersfolksinger.jpg', 'Album cover — fair use (Wikipedia)', 'The Night Muddy Put the Amp Down', 'Kvelden Muddy la fra seg forsterkeren', 'Turn off the lights, put on headphones, and let a 49-year-old Muddy Waters remind you the blues never needed a single watt of electricity to break your heart.', 'Slukk lyset, ta på hodetelefonene, og la en 49 år gammel Muddy Waters minne deg på at bluesen aldri trengte en eneste watt strøm for å knuse hjertet ditt.', 'I still remember the first time I actually sat down and listened to this record properly, no phone, no distractions, just the record. There''s a moment about forty seconds into "My Home Is in the Delta" where Muddy''s voice drops almost to a whisper and you realize you''ve been holding your breath. That''s the whole record in one moment — a man who spent twenty years teaching Chicago how to plug in the blues, suddenly choosing to strip it all back down to nothing but wood, wire and breath.

You can hear the room. You can hear Buddy Guy — young, reverent, deliberately staying out of Muddy''s way — breathing space into every phrase instead of filling it. This isn''t a man performing the blues for an audience; it''s a man remembering exactly why he started playing it in the first place, on a porch in Mississippi long before Chess Records or amplifiers or any of it existed.

If you only know electric Muddy — the Telecaster snarl, the Chess horn sections, "Mannish Boy" swaggering out of a jukebox — this record will genuinely surprise you. It''s quieter, but it hits harder. Some nights this is the only blues record I want to hear at all.', 9.5, 9, 8.5, 9, 9.7, 9.3, 'Kjell Mersland', 'published', '2026-05-04 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'robert-johnson-king-of-the-delta-blues-singers', 'robert-johnson', 'Robert Johnson', 'King of the Delta Blues Singers', 1961, 'Columbia Records', 'Delta Blues', 'https://upload.wikimedia.org/wikipedia/en/e/e6/KotDBS1.jpg', 'Album cover — fair use (Wikipedia)', 'The Record That Sounds Like a Ghost Story Because It Basically Is One', 'Platen som høres ut som en spøkelseshistorie — fordi den nesten er det', 'Twenty-nine songs, one man, one guitar, and a legend that''s swallowed the actual music whole — until you actually press play, and it swallows you instead.', 'Tjueni sanger, én mann, én gitar, og en legende som har svelget selve musikken hel — helt til du faktisk trykker play, og den svelger deg i stedet.', 'Everyone tells you the crossroads story before they tell you to actually listen to the music, and that''s a shame, because the myth undersells what''s really happening on this record. Forget the devil for a second. Listen to what one pair of hands is doing on "Cross Road Blues" — there''s a bassline, a rhythm and a lead melody happening at the same time, from a single acoustic guitar, and it still sounds like a magic trick nine decades later.

What gets me every time is the voice. It cracks. It jumps registers mid-line like he can''t quite contain what he''s singing about. "Hellhound on My Trail" doesn''t sound like a performance — it sounds like a man who genuinely believes something is chasing him, and by the second verse you believe it too. The hiss and crackle of the original 1930s equipment doesn''t get in the way of that; if anything it makes the whole thing feel more like something you shouldn''t have found.

I''ve played this record for people who claim they don''t like old blues, expecting polite nodding, and watched them go completely silent instead. Clapton, Dylan, Keith Richards — they all say the same thing about hearing this for the first time: it rearranges something in you. It still does.', 9.3, 9.6, 7.5, 9.8, 9.9, 9.4, 'Kjell Mersland', 'published', '2026-05-11 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'bb-king-live-at-the-regal', 'bb-king', 'B.B. King', 'Live at the Regal', 1965, 'ABC-Paramount', 'Soul Blues / Live', 'https://upload.wikimedia.org/wikipedia/en/2/2f/BB_King-Live_at_the_Regal_%28album_cover%29.jpg', 'Album cover — fair use (Wikipedia)', 'The Night the Regal Theater Nearly Came Apart', 'Kvelden Regal Theater nesten falt fra hverandre', 'Close your eyes during the opening seconds of "Every Day I Have the Blues" and you''re standing in that Chicago crowd on a November night in 1964, and nothing on record has ever topped it.', 'Lukk øynene under de første sekundene av "Every Day I Have the Blues", så står du midt i det publikummet i Chicago en novemberkveld i 1964 — og ingenting på plate har noen gang toppet det.', 'You hear the crowd before you hear a single note of guitar, and that''s not an accident — it''s the whole point. This is a room that has seen B.B. King a dozen times before and still can''t contain itself the second the band kicks in. That kind of reaction can''t be faked or overdubbed. It''s the sound of an audience that already loves every song that''s about to happen.

What kills me is how much King is talking to the crowd through Lucille, mid-solo, like he''s narrating his own performance because he genuinely can''t help himself — "Sweet Little Angel" turns into a call-and-response between his voice, his guitar, and eight hundred people who are all in on it together. By "It''s My Own Fault" you''re not listening to a concert anymore, you''re inside one.

I''ve heard people say recorded blues can never capture what the music is actually for — that you had to be there. This is the one record that makes a liar out of that argument. Rolling Stone ranks it among the greatest albums ever made in any genre and honestly, on the right night, with the volume up, it''s hard to disagree.', 9.7, 9.5, 8.8, 8.9, 9.9, 9.4, 'Kjell Mersland', 'published', '2026-05-18 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'howlin-wolf-moanin-in-the-moonlight', 'howlin-wolf', 'Howlin'' Wolf', 'Moanin'' in the Moonlight', 1959, 'Chess Records', 'Chicago Blues', 'https://upload.wikimedia.org/wikipedia/en/4/42/Howlin%27_Wolf_Moanin%27_in_the_Moonlight.jpg', 'Album cover — fair use (Wikipedia)', 'The Sound That Still Makes the Hair on Your Arms Stand Up', 'Lyden som fortsatt får hårene på armen til å reise seg', 'Six foot three, close to 300 pounds, a voice like gravel being shovelled — nearly seventy years on, Howlin'' Wolf''s debut still sounds less like music and more like a warning.', '195 centimeter, nesten 140 kilo, en stemme som grus som skuffes — nesten sytti år senere høres Howlin'' Wolfs debut fortsatt mindre ut som musikk og mer som en advarsel.', 'There''s a specific kind of quiet you go when "Smokestack Lightnin''" starts — that one-chord vamp just circling and circling while Hubert Sumlin''s guitar does something that doesn''t resolve, doesn''t sit still, doesn''t behave. It''s genuinely unsettling in a way I don''t think any other blues record from this era manages. Wolf doesn''t sing the blues so much as he seems barely restrained by it.

Compare him to Muddy Waters — suave, controlled, in command of the room — and Wolf is the opposite on every axis. "Moanin'' at Midnight" sounds like something escaping rather than something performed. I''ve put this record on for friends who think they know what Chicago blues sounds like and watched their whole face change halfway through the first track.

Cream, Zeppelin, the Doors, the Stones — they all went straight to this well and covered these songs, and none of them, in my opinion, ever quite captured what makes the originals so physically unnerving. This isn''t background music. This is a record that requires you to actually sit with it, and I still can''t fully explain why I love returning to something that scares me a little every time.', 9.8, 9.2, 7.8, 9, 9.6, 9.1, 'Kjell Mersland', 'published', '2026-06-01 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'albert-king-born-under-a-bad-sign', 'albert-king', 'Albert King', 'Born Under a Bad Sign', 1967, 'Stax Records', 'Texas Blues / Soul Blues', 'https://upload.wikimedia.org/wikipedia/en/3/32/BornUnderABadSign.jpg', 'Album cover — fair use (Wikipedia)', 'The Bend That Changed How an Entire Generation Held a Guitar', 'Bøyningen som forandret måten en hel generasjon holdt gitaren på', 'One upside-down Flying V, one impossibly patient man, and a single string bend so massive it basically wrote the next fifty years of blues-rock guitar by itself.', 'Én opp-ned Flying V, én utrolig tålmodig mann, og én strengbøyning så enorm at den nærmest skrev de neste femti årene med blues-rock-gitar helt alene.', 'The first time you actually see footage of Albert King playing — left-handed, holding a right-handed Flying V flipped over, strings tuned down into something nobody''s ever fully agreed on — it looks almost impossible. Then you hear "Born Under a Bad Sign" and you understand: he wasn''t fighting the guitar, he''d just decided the instrument had to bend to him instead of the other way around.

What gets me about this record is the patience. Booker T. & the M.G.''s and the Memphis Horns are locked into these tight, economical Stax grooves underneath him, and King just refuses to hurry. He''ll hold one note, bent almost past where you think a string should physically go, longer than feels comfortable — and that discomfort is the whole point. Clapton, Hendrix, SRV all chased that exact feeling their entire careers and never quite got there.

"Crosscut Saw" still makes me want to pull the car over. This isn''t a record you put on in the background — it''s a record that reaches out of the speakers and grabs you by the collar, one impossibly held note at a time.', 9.2, 9.7, 9, 9.3, 9.1, 9.3, 'Kjell Mersland', 'published', '2026-06-08 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'freddie-king-freddy-king-sings', 'freddie-king', 'Freddie King', 'Freddy King Sings', 1961, 'King Records', 'Texas Blues / Chicago Blues', 'https://upload.wikimedia.org/wikipedia/en/b/bd/Freddy_King_Sings_album_cover.jpg', 'Album cover — fair use (Wikipedia)', 'The Singer Everyone Forgets Because the Guitarist Was Too Good', 'Vokalisten alle glemmer fordi gitaristen var for god', 'History remembers Freddie King for his guitar and quietly forgot he could absolutely tear your heart out with just his voice — this record is the proof they left behind.', 'Historien husker Freddie King for gitaren og glemte stille at han kunne rive hjertet rett ut av deg med bare stemmen — denne platen er beviset de etterlot.', 'Everyone talks about Freddie King''s guitar first — fair enough, it''s extraordinary — but this record is where I fell for his voice instead, and I don''t think enough people give it the credit it deserves. "Have You Ever Loved a Woman" is genuinely one of the most devastating vocal performances in blues, full stop. Clapton knew it too — that''s exactly why Derek and the Dominos covered it, note for aching note.

What I love about this album is how unshowy it is. King grew up absorbing T-Bone Walker''s Texas precision on one side and Chicago''s amplified grit on the other, and here you can hear both traditions arguing it out inside one guy, in real time. "I''m Tore Down" shuffles along with this rhythmic snap that just refuses to let you sit still, and then two songs later he''s wrecking you emotionally with a slow blues that barely raises its voice.

This wasn''t cut to be a landmark. It was a working guitarist and singer cutting sides for a regional label, with zero idea that blues-rock players would still be studying every phrase sixty years on. That''s exactly why it still feels so alive — nobody was performing for history, they were just playing.', 9, 9.4, 8.3, 8.7, 8.8, 8.8, 'Kjell Mersland', 'published', '2026-06-15 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'buddy-guy-damn-right-ive-got-the-blues', 'buddy-guy', 'Buddy Guy', 'Damn Right, I''ve Got the Blues', 1991, 'Silvertone Records', 'Chicago Blues / Blues Rock', 'https://upload.wikimedia.org/wikipedia/en/d/d4/BuddyGuy-DamnRight-cover.jpeg', 'Album cover — fair use (Wikipedia)', 'Thirty Years Late and Somehow Perfectly on Time', 'Tretti år for sent og på en eller annen måte helt presist i tide', 'After decades of being told he was ''too much'' for the studio, Buddy Guy finally got a record built entirely around the fact that too much was always the entire point.', 'Etter tiår med å bli fortalt at han var ''for mye'' for studioet, fikk Buddy Guy endelig en plate bygget helt rundt det faktum at ''for mye'' alltid var hele poenget.', 'There''s something almost unbearably satisfying about knowing the backstory before you hit play on the title track. Leonard Chess reportedly thought Buddy Guy''s wild, theatrical style was too much for a Chess Records session back in the sixties — too loud, too unpredictable, too everything. Thirty years later, here''s an entire album built to give him exactly the room Chess never did, and you can hear him take every inch of it.

Eric Clapton shows up on "Early in the Morning" and it plays less like a guest verse and more like a student publicly thanking a teacher he never got to properly repay — Hendrix, Clapton, Vaughan all built entire careers out of what Buddy Guy was doing in Chicago clubs decades earlier, largely unheard outside them. Hearing him finally get his own spotlight, with the people he inspired standing right beside him, hits different every single time.

Is it slicker than his sixties work? Sure. But the playing itself hasn''t lost an ounce of danger — if anything, thirty years of being overlooked put an extra edge on it. This is the record that reintroduced an entire generation to one of the last living bridges between Chicago blues and the rock guitar it created, and it still sounds like a man with something to prove.', 9.1, 9.5, 9, 8.8, 9, 9.1, 'Kjell Mersland', 'published', '2026-06-22 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'stevie-ray-vaughan-texas-flood', 'stevie-ray-vaughan', 'Stevie Ray Vaughan', 'Texas Flood', 1983, 'Epic Records', 'Texas Blues', 'https://upload.wikimedia.org/wikipedia/en/5/5e/StevieRayVaughanTexasFlood.jpg', 'Album cover — fair use (Wikipedia)', 'A 28-Year-Old with Nothing to Lose and Everything to Prove', 'En 28-åring med ingenting å tape og alt å bevise', 'Cut essentially live over one weekend for pocket change, Texas Flood sounds exactly like what it was — a guitarist with everything on the line, refusing to hold anything back.', 'Spilt inn nærmest live på én helg for småpenger — Texas Flood høres ut akkurat som det det var: en gitarist med alt på spill, som nekter å holde noe tilbake.', '"Pride and Joy" is the song everyone knows, and fair enough, it''s an instant shuffle so effortless it became a standard within months. But I always end up going back to the title track for the real gut-punch. It''s a slow, cavernous 12-bar blues, and you can hear Vaughan physically attacking the strings — an almost violent intensity that somehow, impossibly, never loses control of a single note.

Recorded essentially live off an unbilled, jaw-dropping set at Montreux in ''82 that nobody expected, for a few thousand dollars, in a room with almost no overdubs — this is a guitarist with everything to prove and nothing to fall back on if it didn''t land. That hunger is all over the record. Then "Lenny," written for his wife, shows up and suddenly he''s tender, patient, completely different — proof this wasn''t a one-note guy even at 28.

Vaughan got more polished later, more famous, arguably more accomplished. But he never sounded hungrier than he does here, and that hunger is exactly why I keep coming back to this one over the rest of his catalogue. This is the sound of blues guitar refusing to become a museum piece.', 8.8, 9.8, 9, 8.9, 9.2, 9.1, 'Kjell Mersland', 'published', '2026-06-29 10:00:00');

-- Artist profile stubs for the 6 modern European reviewed artists
INSERT INTO artists (id, slug, name, tag, era, active_years, img, country, origin, sort_order, short_en, short_no) VALUES (lower(hex(randomblob(16))), 'kid-andersen', 'Kid Andersen', 'Modern', '1998–present', '1998–present', 'https://upload.wikimedia.org/wikipedia/commons/b/b7/Kid-Andersen-Coloma-2009.jpg', 'Norway', 'Kristiansand, Norway → San Jose, California', 910, 'Norwegian-born guitarist, producer and owner of Greaseland Studios in San Jose. Longtime member of Rick Estrin & the Nightcats, a Blues Music Award and Grammy-nominated producer, and one of the most in-demand session guitarists in modern blues.', 'Norskfødt gitarist, produsent og eier av Greaseland Studios i San Jose. Mangeårig medlem av Rick Estrin & the Nightcats, Blues Music Award- og Grammy-nominert produsent, og en av de mest etterspurte sesjonsgitaristene i moderne blues.');
INSERT INTO artists (id, slug, name, tag, era, active_years, img, country, origin, sort_order, short_en, short_no) VALUES (lower(hex(randomblob(16))), 'bjorn-berge', 'Bjørn Berge', 'Modern', '1990s–present', '1990s–present', 'https://upload.wikimedia.org/wikipedia/commons/d/d9/Bjoern_Berge_1999.jpg', 'Norway', 'Haugesund, Norway', 910, 'Norwegian one-man-band blues guitarist and vocalist, known for his ferocious 12-string resonator playing and stomp-box percussion, cutting a solo path through blues, rock and funk across more than a dozen albums.', 'Norsk enmanns-orkester-bluesgitarist og vokalist, kjent for sitt rasende 12-strengs resonatorspill og stomp-box-perkusjon, med en solokarriere gjennom blues, rock og funk over mer enn et titalls album.');
INSERT INTO artists (id, slug, name, tag, era, active_years, img, country, origin, sort_order, short_en, short_no) VALUES (lower(hex(randomblob(16))), 'spoonful-of-blues', 'Spoonful of Blues', 'Modern', '2000s–present', '2000s–present', 'https://i.ytimg.com/vi/Zd2by9EFzYI/hqdefault.jpg', 'Norway', 'Notodden, Norway', 910, 'Blues-rock band from Notodden — home of Norway''s biggest blues festival — built around Jostein Forsberg''s vocals and harmonica and Morten Omlid''s guitar, cutting original songs steeped in their hometown''s blues tradition.', 'Blues-rock-band fra Notodden — hjembyen til Norges største bluesfestival — bygget rundt Jostein Forsbergs vokal og munnspill og Morten Omlids gitar, med egne låter dypt forankret i hjembyens blues-tradisjon.');
INSERT INTO artists (id, slug, name, tag, era, active_years, img, country, origin, sort_order, short_en, short_no) VALUES (lower(hex(randomblob(16))), 'thorbjorn-risager', 'Thorbjørn Risager & The Black Tornado', 'Modern', '2000s–present', '2000s–present', 'https://i.ytimg.com/vi/BB37zZWZEXE/hqdefault.jpg', 'Denmark', 'Denmark', 910, 'Denmark''s leading blues band, an eight-piece led by singer-guitarist Thorbjørn Risager, blending Chicago blues stomp with horns, strings and soul that has made them festival headliners across Europe.', 'Danmarks ledende bluesband, et åttemannsband ledet av vokalist/gitarist Thorbjørn Risager, som blander Chicago-blues-stomp med messingblås, strykere og soul — og som har gjort dem til festival-headlinere over hele Europa.');
INSERT INTO artists (id, slug, name, tag, era, active_years, img, country, origin, sort_order, short_en, short_no) VALUES (lower(hex(randomblob(16))), 'elles-bailey', 'Elles Bailey', 'Modern', '2017–present', '2017–present', 'https://i.ytimg.com/vi/WzrFkwLYtYQ/hqdefault.jpg', 'United Kingdom', 'Bristol, England', 910, 'Bristol-based Americana and blues-rock singer-songwriter whose fourth album swept the 2025 UK Blues Awards, winning Album of the Year, Vocalist of the Year and Broadcaster of the Year.', 'Americana- og blues-rock-låtskriver fra Bristol hvis fjerde album feide innom UK Blues Awards 2025 og vant Album of the Year, Vocalist of the Year og Broadcaster of the Year.');
INSERT INTO artists (id, slug, name, tag, era, active_years, img, country, origin, sort_order, short_en, short_no) VALUES (lower(hex(randomblob(16))), 'erja-lyytinen', 'Erja Lyytinen', 'Modern', '2000s–present', '2000s–present', 'https://i.ytimg.com/vi/DFVO0IF9pXM/hqdefault.jpg', 'Finland', 'Mikkeli, Finland', 910, 'Finland''s foremost blues guitarist and vocalist, celebrated for her slide playing and a catalogue that has steadily pulled blues toward 1970s-influenced rock without ever losing the grit.', 'Finlands fremste bluesgitarist og vokalist, kjent for sitt slide-spill og en katalog som gradvis har dratt bluesen mot 1970-talls-inspirert rock uten å miste råskapen.');

-- 6 editor (Kjell Mersland) reviews of modern Norwegian/European blues releases
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, youtube_playlist_id, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'kid-andersen-lisa-andersen-spirits-and-soul', 'kid-andersen', 'Kid Andersen & Lisa "Little Baby" Andersen', 'Spirits and Soul', 2024, 'Little Village Foundation', 'Blues / Soul-Blues', 'https://i.ytimg.com/vi/dHZP1OzIPOM/hqdefault.jpg', 'YouTube — official "Spirits and Soul" album playlist (Kid Andersen - Topic)', 'OLAK5uy_mdzSVIdzzsTD9B3Rt62Y2wdesE5EVD4r0', 'Two Voices, One Roof, Twenty-Two Reasons to Believe in Greaseland', 'To stemmer, ett tak, tjueto grunner til å tro på Greaseland', 'A husband and wife trade the studio back and forth for an entire double album, and somehow neither one of them blinks first.', 'Et ektepar bytter på studioet gjennom et helt dobbeltalbum, og ingen av dem blunker først.', 'I''ve followed Kid Andersen''s fingerprints on other people''s records for years before I ever properly sat down with something under his own name — the man produces, engineers and plays guitar on what feels like half the blues records coming out of California, usually from behind the desk at his own Greaseland Studios. Spirits and Soul is different. It''s the record where he and his wife, Lisa "Little Baby" Andersen, each take a side of a double album and simply let the other one lead.

Kid''s nine songs on "Spirits" are exactly what you''d hope from a guitarist this well-travelled — economical, warm-toned, never showing off for its own sake, happy to step back and let Charlie Musselwhite''s harmonica or a guest vocal take the spotlight. Lisa''s thirteen songs on "Soul" go somewhere rawer and more direct, and honestly, she''s the one who surprised me most on first listen. This isn''t a vanity side project tacked onto a famous guitarist''s name — she holds her half of this record entirely on her own terms.

What I keep coming back to is how unhurried the whole thing feels, for a 22-track double album. Nothing here is trying to prove a point. It''s two people who''ve spent years making other artists sound good, finally taking a turn in front of the microphone together, in a room they clearly both feel completely at home in.

Mine favorittspor: "The Civilized Life" opens Kid''s side and sets the tone immediately — patient, unshowy, exactly the kind of playing that convinces me why he''s the first call for half of Northern California''s blues scene. "Hey, Mr. Reaper," with Charlie Musselwhite sitting in, is worth the price of admission by itself.

Redaktørens dom: A double album is a big ask of any listener, and I won''t pretend every one of the 22 songs needed to be here. But as a portrait of a marriage built inside a recording studio, this is generous, unpretentious and, on Lisa''s side especially, a genuine discovery.', 8.9, 9.3, 9.4, 8.7, 8.8, 9, 'Kjell Mersland', 'published', '2026-07-06 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, youtube_playlist_id, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'bjorn-berge-introducing-steelfinger-slim', 'bjorn-berge', 'Bjørn Berge', 'Introducing SteelFinger Slim', 2024, 'Blue Mood Records', 'Acoustic Blues / One-Man-Band', 'https://f4.bcbits.com/img/a0138630987_10.jpg', 'Album cover — Bandcamp (Blue Mood Records)', 'W5fgAgVsS-U', 'One Man, One Guitar, and Absolutely No Need for a Backing Band', 'Én mann, én gitar, og overhodet ikke bruk for et backingband', 'Bjørn Berge reminds me, every single time, exactly why the one-man-band format never actually needed anyone else in the room.', 'Bjørn Berge minner meg, hver eneste gang, nøyaktig på hvorfor enmanns-orkester-formatet aldri egentlig trengte noen andre i rommet.', 'There''s something almost stubborn about what Bjørn Berge does — one man, a battered 12-string resonator, a stomp box for a rhythm section, and thirteen studio albums built entirely on the principle that he doesn''t need anyone else''s help. Introducing SteelFinger Slim is his thirteenth, and if anything, the format has only gotten more ferocious with age.

"Mama Said" opens the record and it''s a genuine gut-punch — that resonator sounds like it''s fighting him for control of every note, and his voice, gravelled and completely unbothered, just rides straight over the top. I put this on in the car once and had to turn it down at a red light out of pure instinct, which tells you everything about how physically the record hits.

What gets me is that Berge never sounds like he''s compensating for the missing band. There''s no sense of absence here — the stomp-box percussion and the low, buzzing bass notes he pulls out of that resonator do all the work a rhythm section would, and honestly I think the record is more urgent for not having one.

Mine favorittspor: "Mama Said" for the sheer physical attack of it, and his take on "Spoonful" — a song that''s been covered by half the blues world, and he still finds a way to make it sound like nobody''s touched it before him.

Redaktørens dom: This isn''t a record for background listening — it demands you actually sit with it. If you want proof that one guitar and one voice can still carry an entire album''s weight in 2024, this is it.', 9, 9.5, 8.8, 8.9, 9.3, 9.1, 'Kjell Mersland', 'published', '2026-07-13 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, youtube_playlist_id, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'spoonful-of-blues-songs-from-notodden-norway', 'spoonful-of-blues', 'Spoonful of Blues', 'Songs From Notodden Norway', 2023, 'Bluestown Records', 'Blues / Rock', 'https://i.ytimg.com/vi/Zd2by9EFzYI/hqdefault.jpg', 'YouTube — official track video', 'Zd2by9EFzYI', 'A Postcard From the Town That Blues Built in Norway', 'Et postkort fra byen bluesen bygde i Norge', 'If you want to know what it actually sounds like where I live and breathe this music, start with a band that recorded this two minutes from the festival gates.', 'Om du vil vite hvordan det faktisk høres ut der jeg lever og puster denne musikken, start med et band som spilte dette inn to minutter fra festivalportene.', 'Notodden is where Norway''s biggest blues festival happens every August, and it takes a certain kind of local pride to name your album Songs From Notodden Norway rather than something more universal — but Spoonful of Blues have earned the right. This is their sixth record, cut at the town''s own Juke Joint Studio, and it sounds like a band that''s spent years playing to that exact festival crowd and knows precisely what makes them move.

Jostein Forsberg''s vocals and harmonica sit right up front throughout, with Morten Omlid''s guitar doing the heavy lifting underneath — this is eleven original songs, no filler covers, which is more than I can say for a lot of regional blues records that lean on standards to pad the runtime. "Rollercoaster Ride To Hell" and "Mojo Mama" both have exactly the kind of shuffle that gets a festival tent moving at two in the afternoon.

I won''t pretend this is a record trying to reinvent anything — it''s not. What it does is exactly what a hometown blues band should do: play with total conviction for the people who already love them, and trust that conviction to carry it further than it has any right to.

Mine favorittspor: "Me In Your Arms Tonight" is the one I keep humming days later, and "Mojo Mama" is the one I''d put on a Notodden festival mixtape without a second thought.

Redaktørens dom: This won''t be the record that introduces Notodden to the rest of the blues world, but for those of us who already know the town, it''s exactly right — honest, unpretentious, and proudly local.', 8.3, 8.5, 7.9, 8.2, 8.8, 8.3, 'Kjell Mersland', 'published', '2026-07-20 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, youtube_playlist_id, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'thorbjorn-risager-black-tornado-navigation-blues', 'thorbjorn-risager', 'Thorbjørn Risager & The Black Tornado', 'Navigation Blues', 2022, 'Provogue / Mascot Label Group', 'Chicago Blues / Soul', 'https://i.ytimg.com/vi/BB37zZWZEXE/hqdefault.jpg', 'YouTube — official music video', 'BB37zZWZEXE', 'Denmark''s Biggest Blues Band Still Hasn''t Run Out of Road', 'Danmarks største blueband har fortsatt ikke gått tom for vei', 'Eight musicians, a full horn section, and not one wasted note across an album that proves size and subtlety aren''t opposites.', 'Åtte musikere, full messingblås-seksjon, og ikke én bortkastet tone på et album som beviser at størrelse og finesse ikke er motsetninger.', 'Thorbjørn Risager leads the biggest touring blues outfit to come out of Denmark, an eight-piece with horns and backing vocals that could easily tip over into bloat in less careful hands. Navigation Blues, produced by Søren Bøjgaard, doesn''t make that mistake once across its twelve tracks — every horn stab and string swell earns its place.

The title track sets the template: pre-war blues stomp underneath, but dressed with a modern production sheen that never feels like it''s compensating for a lack of grit. Risager''s voice has that weathered, lived-in quality that lets a big arrangement breathe around it instead of fighting it, and "The Way You Make Me Feel" shows the band at its most soulful, horns and all.

What impresses me most is the discipline. Eight musicians is a lot of people to keep out of each other''s way, and this record never once sounds crowded — it sounds like a band that has spent enough years on European festival stages to know exactly when to hold back.

Mine favorittspor: the title track "Navigation Blues" for how confidently it announces the whole record, and "Watch The Sun Go Down" for the horn arrangement alone.

Redaktørens dom: This is European blues at its most confidently big-band, and it''s earned every bit of the festival headline slots it''s picked up since release.', 8.8, 9.1, 9.2, 8.6, 8.9, 8.9, 'Kjell Mersland', 'published', '2026-07-27 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, youtube_playlist_id, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'elles-bailey-beneath-the-neon-glow', 'elles-bailey', 'Elles Bailey', 'Beneath the Neon Glow', 2024, 'Independent', 'Americana / Blues-Rock', 'https://i.ytimg.com/vi/WzrFkwLYtYQ/hqdefault.jpg', 'YouTube — official music video', 'WzrFkwLYtYQ', 'The Album That Finally Got Elles Bailey the Trophies She Deserved', 'Albumet som endelig ga Elles Bailey trofeene hun fortjente', 'Three UK Blues Awards in one year isn''t a fluke — it''s a singer-songwriter finally getting the recognition her last three albums were quietly building toward.', 'Tre UK Blues Awards på ett år er ikke tilfeldig — det er en låtskriver som endelig får anerkjennelsen de tre forrige albumene stille bygget opp mot.', 'Bristol''s Elles Bailey has been circling this level of songwriting for three albums now, and Beneath the Neon Glow is where it all clicked at once — Album of the Year, Vocalist of the Year and Broadcaster of the Year at the 2025 UK Blues Awards, which for a genre that doesn''t hand out trophies lightly, is about as decisive a statement as you''ll see.

"Leave The Light On" is the song that made me stop what I was doing the first time it came on — there''s a directness to her voice, more Americana-rock than straight blues most of the time, but with a grain to it that keeps pulling the record back toward the tradition it''s named after. "1972" does something quieter and more personal, and it''s the track that''s stayed with me longest.

What I appreciate is that this doesn''t sound like a record chasing a genre checklist. It sounds like a songwriter who''s stopped worrying about which side of the Americana/blues line she''s supposed to stand on, and just wrote the ten best songs she had.

Mine favorittspor: "Leave The Light On" for the sheer hook of it, and "1972" for the one that actually got under my skin.

Redaktørens dom: This is the sound of an artist arriving fully formed at exactly the record she was always capable of making. The awards are deserved.', 9.2, 8.7, 9, 9.1, 8.8, 9, 'Kjell Mersland', 'published', '2026-08-03 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, youtube_playlist_id, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'erja-lyytinen-waiting-for-the-daylight', 'erja-lyytinen', 'Erja Lyytinen', 'Waiting for the Daylight', 2022, 'Tuohi Records', 'Blues-Rock', 'https://i.ytimg.com/vi/DFVO0IF9pXM/hqdefault.jpg', 'YouTube — official music video', 'DFVO0IF9pXM', 'Finland''s Finest Guitarist Turns Toward 70s Rock and Never Looks Back', 'Finlands beste gitarist vender seg mot 70-talls-rock og ser seg aldri tilbake', 'Self-produced, self-assured, and further from straight blues than any Erja Lyytinen record before it — and all the better for the risk.', 'Egenprodusert, selvsikker, og lenger unna ren blues enn noe tidligere Erja Lyytinen-album — og desto bedre for risikoen.', 'Erja Lyytinen has been Finland''s most reliable blues guitar export for two decades, and Waiting for the Daylight is the record where she stops being reliable in the safe sense and starts taking real chances. Self-produced at her own Hollywood House studio in Helsinki, it leans harder into 1970s European rock than anything in her catalogue before it, and I mean that as a genuine compliment.

The title track was filmed at Raasepori castle for the video, and there''s something fitting about that — this is music that wants space and stone walls around it, not a club stage. Her slide playing is as precise as ever, but the songwriting has opened up, letting tracks like "Bad Seed" and "Last Girl" breathe in ways her more traditional records never quite allowed themselves.

I''ll admit I went in expecting the Erja Lyytinen I already knew, and came out having to recalibrate — this is an artist genuinely moving her sound forward nine albums in, which is rarer than it should be in blues.

Mine favorittspor: the title track for the sheer scale of the production, and "Bad Seed" for how far it pushes away from anything resembling a blues shuffle.

Redaktørens dom: Not the record to start with if you want classic Erja Lyytinen blues guitar — but if you want to hear a genuinely accomplished player still restless enough to change lanes, this is essential.', 8.6, 9.2, 9, 8.8, 8.9, 8.9, 'Kjell Mersland', 'published', '2026-08-10 10:00:00');


INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, youtube_playlist_id, youtube_album_url, title_en, title_no, verdict_en, verdict_no, body_en, tracks, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'oz-and-the-wizards-magic-potion', NULL, 'Oz & the Wizards', 'Magic Potion', 2026, 'Independent Release', 'Delta Blues / Chicago Blues', 'https://yt3.googleusercontent.com/hWMA6F3h7-xJ8IXTAXoCVRN1FJKs12kOnEvyCUCWwkfLP8W3v7HbtWj03SJW65vS3ukwdj60SE6HyMGw=w544-h544-l90-rj', 'Cover image — official YouTube channel art (Oz & the Wizards)', 'OLAK5uy_kvSMSN_stFvrpvDPTEEXkqENAFMQwS-rk', 'https://music.youtube.com/playlist?list=OLAK5uy_kvSMSN_stFvrpvDPTEEXkqENAFMQwS-rk', 'A Kristiansand Juke Joint, Bottled', 'En Kristiansand-jukejoint på flaske', 'Oz & the Wizards prove Kristiansand can bottle the real thing — raw slide guitar, zero gimmicks, and a title track that earns its name.', 'Oz & the Wizards beviser at Kristiansand kan tappe den ekte varen på flaske — rå slidegitar, ingen snarveier, og et tittelspor som fortjener navnet sitt.', 'I''ll be upfront about something: I''ve been waiting years for a Kristiansand band to make a record like this. Oz & the Wizards aren''t trying to modernize the blues or bolt anything new onto it — they''re playing it exactly the way it sounded coming out of Mississippi and Chicago seventy years ago, and doing it with a conviction that makes you forget you''re listening to a band from the south coast of Norway and not a juke joint on Maxwell Street.

Osmund "OZ" Grytdahl''s slide guitar is the first thing that grabs you, and it never lets go. There''s a rawness to his tone — unpolished, biting, occasionally teetering right on the edge of falling apart — that most guitarists spend a career trying to fake and almost never manage. He plays like the guitar owes him something. Behind him, Ole Louis Lilløy''s bass and Oddvar Michaelsen''s drums do exactly what a blues rhythm section is supposed to do: they stay out of the song''s way until the moment they''re needed, then they hit like a freight train. Ten tracks, forty-one minutes and thirty-eight seconds, and not one of them is padding.

"Jezebel" opens the record and tells you everything you need to know inside the first thirty seconds — Grytdahl''s slide cutting through a stomping backbeat, a vocal that sounds like it''s been marinating in cigarette smoke for two decades. "Telephone Blues" follows and tightens the screws even further, all clipped guitar answers and a groove that refuses to sit still. And then there''s "Queen of Evil" — seven and a half minutes of slow-burning, hypnotic menace that is, without question, the record''s centerpiece. It''s the kind of track that shouldn''t work on paper, that long and that patient, and it works entirely because the band trusts the tension enough not to rush toward a release.

The title track, "Magic Potion," closes the album the way a great blues record should: unhurried, a little bit haunted, guitar and voice trading places until you can barely tell which one is actually telling the story. By the time it faded out, I''d already decided I was going to be playing this record for months.

Mine favorittspor: "Queen of Evil" is the one I keep coming back to — the patience of that slide riff, the way the whole band seems to breathe together as it builds toward the end. "Jezebel" is the one I''d play for someone who''s never heard the band, because it makes the entire case in under four minutes.

Redaktørens dom: This is the most convincing straight blues record to come out of Kristiansand in years — no gimmicks, no crossover ambitions, just three musicians who clearly love this music and play it like they mean it. Magic Potion earns its title. Highly recommended.', '[{"title":"Jezebel","duration":"3:55"},{"title":"Telephone Blues","duration":"3:10"},{"title":"Queen of Evil","duration":"7:21"},{"title":"Me and the Devil","duration":"4:27"},{"title":"I Don''t Mind","duration":"4:24"},{"title":"Lincoln Continental","duration":"3:31"},{"title":"Envy","duration":"4:41"},{"title":"Mr Blues","duration":"3:01"},{"title":"Frog in My Room","duration":"2:39"},{"title":"Magic Potion","duration":"4:29"}]', 9, 9.6, 8.7, 9, 9.5, 9.2, 'Kjell Mersland', 'published', '2026-08-11 10:00:00');

UPDATE artists SET
  biography_en = 'If this site has a patron saint, it''s the man on this page. Every artist I write about here, in one way or another, owes something to Charley Patton — and most of them would tell you so themselves, if you asked.

Patton was born around April 1891 in Hinds County, Mississippi, near the town of Edwards, to Bill and Annie Patton — though even that date is debated; some accounts put his birth as early as 1881 or as late as 1887, since nobody thought to write it down at the time. In 1897, when Charley was still a boy, the family moved roughly a hundred miles north to Dockery Plantation, a sprawling 10,000-acre cotton operation near Ruleville that would become, almost by accident, the single most important address in the history of American music. It was there, sometime in the early 1900s, that young Charley fell in with an older Dockery sharecropper and musician named Henry Sloan, who was already playing an early, unrecorded form of the blues. Sloan taught him. Nobody ever recorded a note of what Sloan played, but everything Patton became started at that lesson.

By the time he was a grown man, Patton — a small, wiry figure at around five foot five and maybe 135 pounds — had turned himself into the loudest, most theatrical performer the Delta had ever produced. Witnesses described a voice loud enough to carry 500 yards across a plantation without any amplification, and a stage act that, four decades before Jimi Hendrix, already included playing the guitar behind his head, behind his back, between his legs, on his knees, and throwing it in the air and catching it mid-song without missing a beat. He''d slap the body of the guitar like a drum between phrases — one of the very first recorded uses of what guitarists now call a body slap. He wasn''t just a musician. He was the whole show.

Word of Patton eventually reached H.C. Speir, a Jackson, Mississippi record store owner who moonlighted as a talent scout for the "race records" business. Speir auditioned Patton at Dockery in the spring of 1929 and was impressed enough to send him straight to Paramount Records. On June 14, 1929, Patton travelled to Richmond, Indiana, and recorded fourteen sides in a single day at the Gennett/Starr Piano Company studio — among them "Pony Blues," the record that made him a star across the Delta, along with "A Spoonful Blues" and "Down the Dirt Road Blues," both cut that same afternoon. Paramount''s A&R man Arthur Laibly brought him back twice more that year, to the label''s own studio in the small town of Grafton, Wisconsin, where in November and December 1929 Patton recorded more than twenty additional sides — including the two-part "High Water Everywhere," his devastating first-hand account of the Great Mississippi Flood of 1927, which had drowned the Delta he called home and displaced hundreds of thousands of people, Patton very likely among them.

He went back to Grafton one more time, on May 28, 1930, and this session became almost as legendary as the man himself: Patton travelled up with Son House, Willie Brown and a young pianist named Louise Johnson, all recording for Paramount over the same handful of days — by most accounts the closest thing the acoustic Delta blues era has to a single defining recording session.

In 1933, Patton was nearly killed when someone — accounts differ on exactly who, though a jealous husband is the most commonly cited culprit — cut his throat in an altercation near Holly Ridge. He survived, but it left a visible scar from ear to ear and, by most accounts, permanently changed the texture of his voice on the recordings that followed. By then he''d settled in Holly Ridge with Bertha Lee, a much younger singer who became his last common-law wife and closest musical partner. Early in 1934, the two of them were arrested and jailed in Belzoni, Mississippi after a violent argument. They were bailed out by W.R. Calaway of the American Record Corporation, who brought them to New York City for what turned out to be Patton''s final recording sessions, on January 30, 31 and February 1, 1934. Bertha Lee sang alongside him on several of those sides, including the haunting "Oh Death."

Patton died on April 28, 1934, on the Heathman-Dedham plantation near Indianola, of a mitral valve disorder. He was somewhere around forty-two or forty-three. His death wasn''t reported in any newspaper, and he was buried at Holly Ridge Cemetery without a headstone — for 56 years, one of the most important musicians America ever produced lay in an unmarked grave, until 1990, when Creedence Clearwater Revival''s John Fogerty paid for a proper memorial stone through the Mount Zion Memorial Fund, with the epitaph written by blues historian Jim O''Neal.

None of Patton''s own children went on to become known blues musicians. But almost everyone else did. That''s the story that matters most, and it''s the one I want to tell next.',
  biography_no = 'Hvis dette nettstedet har en skytshelgen, er det mannen på denne siden. Hver eneste artist jeg skriver om her skylder på en eller annen måte Charley Patton noe — og de fleste av dem ville sagt det selv, om du spurte.

Patton ble født rundt april 1891 i Hinds County, Mississippi, nær byen Edwards, som sønn av Bill og Annie Patton — men selv den datoen er omdiskutert; enkelte kilder oppgir fødselsår så tidlig som 1881 eller så sent som 1887, siden ingen tenkte på å skrive det ned den gangen. I 1897, mens Charley fortsatt var et barn, flyttet familien rundt hundre mil nordover til Dockery Plantation, en enorm bomullsplantasje på 10 000 acres nær Ruleville som nesten ved en tilfeldighet skulle bli den aller viktigste adressen i amerikansk musikkhistorie. Det var der, en gang tidlig på 1900-tallet, at unge Charley kom i kontakt med en eldre Dockery-forpakter og musiker ved navn Henry Sloan, som allerede spilte en tidlig, aldri innspilt form for blues. Sloan lærte ham opp. Ingen fikk noensinne spilt inn en eneste tone av det Sloan spilte, men alt Patton senere ble startet med den undervisningen.

Da han var voksen, hadde Patton — en liten, senete skikkelse på rundt 165 centimeter og kanskje 60 kilo — gjort seg selv til den høyeste, mest teatralske utøveren Deltaet noensinne hadde produsert. Vitner beskrev en stemme kraftig nok til å bære 500 yards over en plantasje uten noen form for forsterkning, og et sceneshow som, fire tiår før Jimi Hendrix, allerede inkluderte å spille gitaren bak hodet, bak ryggen, mellom beina, på knærne, og å kaste den i lufta og fange den midt i et spor uten å miste takten. Han slo på gitarkassen som en tromme mellom fraser — en av de aller første innspilte bruken av det gitarister i dag kaller kroppsslag. Han var ikke bare en musiker. Han var hele showet.

Ryktet om Patton nådde etter hvert H.C. Speir, en platebutikkeier i Jackson, Mississippi, som drev med talentspeiding for «race records»-bransjen på si. Speir hørte på Patton på Dockery våren 1929 og ble imponert nok til å sende ham rett til Paramount Records. Den 14. juni 1929 reiste Patton til Richmond, Indiana, og spilte inn fjorten spor på én eneste dag i Gennett/Starr Piano Company-studioet — blant dem «Pony Blues», platen som gjorde ham til en stjerne i hele Deltaet, samt «A Spoonful Blues» og «Down the Dirt Road Blues», begge spilt inn samme ettermiddag. Paramounts A&R-mann Arthur Laibly hentet ham tilbake to ganger til samme år, til selskapets eget studio i den lille byen Grafton, Wisconsin, hvor Patton i november og desember 1929 spilte inn over tjue spor til — deriblant tospors-låten «High Water Everywhere», hans nådeløse skildring på førstehånd av den store Mississippi-flommen i 1927, som druknet Deltaet han kalte hjem og fordrev hundretusenvis av mennesker, høyst sannsynlig Patton selv iberegnet.

Han dro tilbake til Grafton én gang til, 28. mai 1930, og denne økten ble nesten like legendarisk som mannen selv: Patton reiste opp sammen med Son House, Willie Brown og en ung pianist ved navn Louise Johnson, og alle spilte inn for Paramount over de samme dagene — ifølge de fleste den nærmeste tingen den akustiske Delta-bluesæraen har til én enkelt definerende innspillingsøkt.

I 1933 ble Patton nesten drept da noen — kildene er uenige om nøyaktig hvem, men en sjalu ektemann er den mest siterte gjerningsmannen — skar over halsen hans i et basketak nær Holly Ridge. Han overlevde, men det etterlot et synlig arr fra øre til øre og, ifølge de fleste beretninger, endret stemmen hans permanent på innspillingene som fulgte. På den tiden hadde han slått seg ned i Holly Ridge med Bertha Lee, en mye yngre sangerinne som ble hans siste samboerkone og nærmeste musikalske partner. Tidlig i 1934 ble de to arrestert og satt i fengsel i Belzoni, Mississippi, etter en voldsom krangel. De ble løslatt mot kausjon av W.R. Calaway fra American Record Corporation, som tok dem med til New York City for det som skulle bli Pattons siste innspillingsøkter, 30. og 31. januar samt 1. februar 1934. Bertha Lee sang sammen med ham på flere av disse sporene, deriblant den gripende «Oh Death».

Patton døde 28. april 1934 på Heathman-Dedham-plantasjen nær Indianola, av en mitralklaffsykdom. Han var et sted mellom førtito og førtitre år gammel. Dødsfallet hans ble ikke omtalt i noen avis, og han ble gravlagt på Holly Ridge Cemetery uten gravstein — i 56 år lå en av de viktigste musikerne Amerika noensinne har frembrakt i en umerket grav, helt til 1990, da John Fogerty fra Creedence Clearwater Revival betalte for en skikkelig minnestein gjennom Mount Zion Memorial Fund, med et epitaf skrevet av blueshistorikeren Jim O''Neal.

Ingen av Pattons egne barn ble noensinne kjente bluesmusikere. Men nesten alle andre ble det. Det er historien som betyr mest, og den vil jeg fortelle nå.',
  influence_en = 'Charley Patton''s most direct student was Chester Burnett — Howlin'' Wolf — who met him at Dockery around 1930 and, by his own account for the rest of his life, learned not just guitar technique from Patton but the whole idea of a blues performance as a piece of theatre: the growl, the floor-crawling, the guitar tricks, all of it traces straight back to what Wolf watched Patton do on that same plantation. John Lee Hooker also came up under Patton''s shadow at Dockery, absorbing the same driving, hypnotic single-chord grooves that would define his own sound decades later on records like "Boogie Chillen''." A teenage Robert Johnson watched Patton perform around the Delta before he''d recorded a single note of his own, and Son House — Patton''s contemporary, sometime travelling companion, and probably the second-most important Delta bluesman on record — carried Patton''s raw, percussive attack directly into the style he would later teach to a young man named McKinley Morganfield, better known as Muddy Waters. Bukka White, another Delta contemporary who knew Patton''s records inside out, passed that same tradition on to his own cousin — B.B. King. It''s a straight, unbroken line: Patton to Wolf, Patton to House to Muddy, Patton to White to King. Musicologist Robert Palmer, who studied this lineage as closely as anyone, called Patton "one of the most important American musicians of the twentieth century" — and every time I put on a Muddy Waters or Howlin'' Wolf record, I''m reminded he wasn''t exaggerating.',
  influence_no = 'Charley Pattons mest direkte elev var Chester Burnett — Howlin'' Wolf — som møtte ham på Dockery rundt 1930 og, ifølge sin egen fortelling resten av livet, lærte ikke bare gitarteknikk av Patton, men hele ideen om en bluesopptreden som teater: knurringen, det å krype på gulvet, gitartriksene — alt sammen kan spores rett tilbake til det Wolf så Patton gjøre på den samme plantasjen. John Lee Hooker vokste også opp i Pattons skygge på Dockery, og tok til seg de samme drivende, hypnotiske enkeltakkord-groovene som skulle definere hans egen lyd flere tiår senere på plater som «Boogie Chillen''». En tenåring ved navn Robert Johnson så Patton opptre rundt om i Deltaet før han selv hadde spilt inn en eneste tone, og Son House — Pattons samtidige, tidvise reisefølge, og trolig den nest viktigste Delta-bluesmannen på plate — bar Pattons rå, perkussive spillestil direkte videre inn i stilen han senere skulle lære bort til en ung mann ved navn McKinley Morganfield, bedre kjent som Muddy Waters. Bukka White, en annen Delta-samtidig som kjente Pattons plater ut og inn, førte den samme tradisjonen videre til sin egen fetter — B.B. King. Det er en rett, ubrutt linje: Patton til Wolf, Patton til House til Muddy, Patton til White til King. Musikkhistorikeren Robert Palmer, som studerte denne slektslinjen grundigere enn de fleste, kalte Patton «en av de viktigste amerikanske musikerne på 1900-tallet» — og hver gang jeg setter på en Muddy Waters- eller Howlin'' Wolf-plate, blir jeg minnet på at han ikke overdrev.',
  signature_songs_i18n = '{"en":["Pony Blues","High Water Everywhere","Down the Dirt Road Blues","A Spoonful Blues","Oh Death","Screamin'' and Hollerin'' the Blues"],"no":["Pony Blues","High Water Everywhere","Down the Dirt Road Blues","A Spoonful Blues","Oh Death","Screamin'' and Hollerin'' the Blues"]}',
  influences_i18n = '{"en":["Henry Sloan"],"no":["Henry Sloan"]}',
  family_i18n = '{"en":[{"relation":"Partner","name":"Bertha Lee Pate","note":"Patton''s last common-law wife and closest musical partner in his final years; she sang alongside him on several 1934 Vocalion recordings, including \"Oh Death.\""},{"relation":"Children","name":"No known children in music","note":"None of Patton''s children are documented to have become known blues musicians."}],"no":[{"relation":"Samboer/kone","name":"Bertha Lee Pate","note":"Pattons siste samboerkone og nærmeste musikalske partner i hans siste leveår; hun sang sammen med ham på flere Vocalion-innspillinger i 1934, deriblant «Oh Death»."},{"relation":"Barn","name":"Ingen kjente barn i musikkbransjen","note":"Ingen av Pattons barn er dokumentert å ha blitt kjente bluesmusikere."}]}',
  formative_i18n = '{"en":["Moved with his family to Dockery Plantation in 1897, where he met Henry Sloan, the older musician who taught him the rudiments of the blues.","Auditioned for talent scout H.C. Speir in Jackson, Mississippi, in early 1929, leading directly to his first Paramount recording session.","Recorded 14 sides in a single day at Gennett Studios in Richmond, Indiana on June 14, 1929, including his breakout hit \"Pony Blues.\"","Lived through the Great Mississippi Flood of 1927, an experience that became the basis for \"High Water Everywhere.\"","Nearly killed in 1933 when his throat was cut in an altercation near Holly Ridge — he survived, but his voice was permanently changed.","Escorted to New York City in early 1934 by producer W.R. Calaway for his final recording sessions, after being bailed out of a Belzoni, Mississippi jail."],"no":["Flyttet med familien til Dockery Plantation i 1897, hvor han møtte Henry Sloan, den eldre musikeren som lærte ham bluesens grunnleggende teknikker.","Ble hørt av talentspeideren H.C. Speir i Jackson, Mississippi, tidlig i 1929, noe som ledet direkte til hans første innspillingsøkt for Paramount.","Spilte inn 14 spor på én dag i Gennett Studios i Richmond, Indiana, 14. juni 1929, deriblant gjennombruddshiten «Pony Blues».","Levde gjennom den store Mississippi-flommen i 1927, en opplevelse som ble grunnlaget for «High Water Everywhere».","Ble nesten drept i 1933 da halsen hans ble skåret opp i et basketak nær Holly Ridge — han overlevde, men stemmen ble varig endret.","Ble eskortert til New York City tidlig i 1934 av produsent W.R. Calaway for sine siste innspillingsøkter, etter å ha blitt løslatt mot kausjon fra et fengsel i Belzoni, Mississippi."]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Stella Grand Concert (Oscar Schmidt)","years":"c. 1920s–1934","note":"According to an account researcher Gayle Dean Wardlow recorded from the Reverend Pearly Brown, who knew Patton personally, his regular working guitar was a black Stella with a white neck — the cheap, mass-produced flat-top that talent scout H.C. Speir said \"all\" the Delta bluesmen he auditioned played."},{"category":"Gitar","name":"Stromberg-Voisinet parlor guitar","years":"1929","note":"The guitar visible in the single surviving photograph of Patton — the 1929 Paramount publicity portrait — has been identified by guitar historians as a Stromberg-Voisinet parlor model rather than a Stella, though it''s unclear whether this was his usual instrument or one borrowed for the photo session."},{"category":"Gitar","name":"Unknown model (New York, 1934)","years":"1934","note":"No photograph survives from Patton''s final Vocalion sessions in New York, so the guitar he used there is undocumented. We could not verify claims of a specific Gibson model from any reliable historical source, so we''re not asserting one here."},{"category":"Annet","name":"Glass bottleneck slide","note":"Used across his recordings for the whining, vocal-like slide lines that became a Delta blues signature, most audible on tracks like \"High Water Everywhere.\""},{"category":"Annet","name":"Guitar-body percussion","note":"Patton''s recordings contain some of the earliest documented uses of a body slap — striking the guitar''s top with the palm or thumb between vocal lines to keep rhythm, decades before it became a standard technique."},{"category":"Vokal","name":"Vocals","note":"Contemporaries described a voice loud enough to carry roughly 500 yards across open ground without amplification. The 1933 throat-cutting incident permanently altered its texture on his final 1934 recordings."}],"no":[{"category":"Gitar","name":"Stella Grand Concert (Oscar Schmidt)","years":"ca. 1920-tallet–1934","note":"Ifølge en beretning forskeren Gayle Dean Wardlow fikk fra pastor Pearly Brown, som kjente Patton personlig, var hans faste arbeidsgitar en svart Stella med hvit hals — den billige, masseproduserte flattopp-gitaren som talentspeideren H.C. Speir sa at «alle» Delta-bluesmennene han hørte på, spilte."},{"category":"Gitar","name":"Stromberg-Voisinet parlorgitar","years":"1929","note":"Gitaren som synes på det eneste bevarte fotografiet av Patton — Paramounts publisitetsportrett fra 1929 — er av gitarhistorikere identifisert som en Stromberg-Voisinet parlormodell snarere enn en Stella, men det er uklart om dette var hans vanlige instrument eller ett lånt til fotograferingen."},{"category":"Gitar","name":"Ukjent modell (New York, 1934)","years":"1934","note":"Ingen fotografier er bevart fra Pattons siste Vocalion-økter i New York, så gitaren han brukte der er udokumentert. Vi klarte ikke å verifisere påstander om en spesifikk Gibson-modell fra noen pålitelig historisk kilde, og påstår derfor ikke det her."},{"category":"Annet","name":"Glass-bottleneck slide","note":"Brukt gjennomgående på innspillingene hans til de klagende, vokal-lignende slide-linjene som ble et Delta-blues-varemerke, tydeligst på spor som «High Water Everywhere»."},{"category":"Annet","name":"Perkusjon på gitarkassen","note":"Pattons innspillinger inneholder noen av de tidligste dokumenterte bruken av et kroppsslag — å slå på gitarens lokk med håndflaten eller tommelen mellom vokallinjer for å holde rytmen, tiår før det ble en standardteknikk."},{"category":"Vokal","name":"Vokal","note":"Samtidige beskrev en stemme kraftig nok til å bære omtrent 500 yards over åpen mark uten forsterkning. Halskuttingen i 1933 endret klangen permanent på hans siste innspillinger fra 1934."}]}',
  anecdotes_i18n = '{"en":["Patton''s stage act — playing the guitar behind his head, behind his back, between his legs, and tossing it in the air without breaking rhythm — predates Jimi Hendrix''s showmanship by roughly four decades, and directly shaped how his student Howlin'' Wolf performed for the rest of his career.","\"High Water Everywhere\" wasn''t hypothetical: the Great Mississippi Flood of 1927 devastated the Delta plantations Patton lived and worked on, and his two-part recording is now regarded as one of the most vivid first-hand musical accounts of the disaster.","In 1933, Patton was nearly killed when someone cut his throat in an altercation near Holly Ridge. He survived with a visible scar from ear to ear — and a voice that never fully recovered its old range on record.","Talent scout H.C. Speir, who first sent Patton to Paramount Records, later said the Delta bluesmen he auditioned \"all played the old cheap Stella guitars, across the board\" — a detail that matches the black Stella described as Patton''s regular instrument.","Patton lay in an unmarked grave at Holly Ridge Cemetery for 56 years until 1990, when John Fogerty of Creedence Clearwater Revival paid for a proper headstone through the Mount Zion Memorial Fund."],"no":["Pattons sceneshow — å spille gitaren bak hodet, bak ryggen, mellom beina, og kaste den i lufta uten å miste takten — kom omtrent fire tiår før Jimi Hendrix'' scenetriks, og formet direkte måten hans elev Howlin'' Wolf opptrådte på resten av karrieren.","«High Water Everywhere» var ikke hypotetisk: den store Mississippi-flommen i 1927 ødela Delta-plantasjene Patton bodde og arbeidet på, og tosporsinnspillingen hans regnes i dag som en av de mest levende førstehånds musikalske skildringene av katastrofen.","I 1933 ble Patton nesten drept da noen skar over halsen hans i et basketak nær Holly Ridge. Han overlevde med et synlig arr fra øre til øre — og en stemme som aldri helt fikk tilbake sitt gamle register på plate.","Talentspeideren H.C. Speir, som først sendte Patton til Paramount Records, sa senere at Delta-bluesmennene han hørte på «alle spilte de gamle, billige Stella-gitarene, uten unntak» — en detalj som stemmer med den svarte Stellaen som beskrives som Pattons faste instrument.","Patton lå i en umerket grav på Holly Ridge Cemetery i 56 år, helt til 1990, da John Fogerty fra Creedence Clearwater Revival betalte for en skikkelig gravstein gjennom Mount Zion Memorial Fund."]}',
  collaborators_i18n = '{"en":[{"name":"Willie Brown","note":"Fellow Dockery-area guitarist and frequent travelling companion; accompanied Patton to several recording sessions, including the famous May 1930 Grafton session."},{"name":"Son House","note":"Contemporary and sometime travelling partner; present at the May 1930 Grafton, Wisconsin sessions. House later passed elements of Patton''s raw, percussive style on to a young Muddy Waters."},{"name":"Son Sims","note":"Delta fiddler and songwriter who accompanied Patton on record across several sessions between 1929 and 1934."},{"name":"Louise Johnson","note":"Pianist who travelled to the May 1930 Grafton session with Patton, Son House and Willie Brown, recording four sides of her own during the same visit."},{"name":"Bertha Lee Pate","note":"Patton''s last common-law wife; sang alongside him on several tracks from his final 1934 Vocalion sessions in New York, including \"Oh Death.\""}],"no":[{"name":"Willie Brown","note":"Gitarist fra samme Dockery-miljø og hyppig reisefølge; ble med Patton til flere innspillingsøkter, deriblant den berømte Grafton-økten i mai 1930."},{"name":"Son House","note":"Samtidig og tidvis reisefølge; til stede under Grafton-øktene i Wisconsin i mai 1930. House videreførte senere elementer av Pattons rå, perkussive stil til en ung Muddy Waters."},{"name":"Son Sims","note":"Delta-fiolinist og låtskriver som akkompagnerte Patton på plate over flere økter mellom 1929 og 1934."},{"name":"Louise Johnson","note":"Pianist som reiste til Grafton-økten i mai 1930 sammen med Patton, Son House og Willie Brown, og spilte inn fire egne spor under samme besøk."},{"name":"Bertha Lee Pate","note":"Pattons siste samboerkone; sang sammen med ham på flere spor fra hans siste Vocalion-økter i New York i 1934, deriblant «Oh Death»."}]}',
  discography_i18n = '{"en":[{"year":1929,"title":"Richmond, Indiana session (Gennett / Starr Piano Co. studio)","producer":"H.C. Speir (talent scout)","label":"Paramount Records","notes":"First recording session, June 14, 1929 — 14 sides cut in a single day, including \"Pony Blues,\" \"A Spoonful Blues\" and \"Down the Dirt Road Blues.\"","musicians":[],"youtube_id":"_xWqtiFJKfs"},{"year":1929,"title":"Grafton, Wisconsin sessions (Paramount studio)","producer":"Arthur Laibly (Paramount A&R)","label":"Paramount Records","notes":"November–December 1929 — over twenty additional sides, including the two-part \"High Water Everywhere,\" his account of the 1927 Mississippi flood.","musicians":[],"youtube_id":"Ctt1LDAiZN4"},{"year":1930,"title":"Grafton, Wisconsin session (with Son House, Willie Brown & Louise Johnson)","producer":"Arthur Laibly (Paramount A&R)","label":"Paramount Records","notes":"May 28, 1930 — widely regarded as one of the defining sessions of the acoustic Delta blues era.","musicians":[{"name":"Son House","instrument":"Guitar/Vocals"},{"name":"Willie Brown","instrument":"Guitar"},{"name":"Louise Johnson","instrument":"Piano"},{"name":"Son Sims","instrument":"Fiddle"}],"youtube_id":"3o4ol6DmeKc"},{"year":1934,"title":"New York City sessions (final recordings)","producer":"W.R. Calaway (American Record Corporation / Vocalion)","label":"Vocalion Records","notes":"January 30–31 and February 1, 1934 — Patton''s last recordings, made after Calaway bailed him and Bertha Lee out of a Belzoni, Mississippi jail. Several sides feature Bertha Lee''s vocals, including \"Oh Death.\"","musicians":[{"name":"Bertha Lee Pate","instrument":"Vocals"}],"youtube_id":"JwC9_ud4Oyo"}],"no":[{"year":1929,"title":"Richmond, Indiana-økten (Gennett / Starr Piano Co.-studioet)","producer":"H.C. Speir (talentspeider)","label":"Paramount Records","notes":"Første innspillingsøkt, 14. juni 1929 — 14 spor spilt inn på én dag, deriblant «Pony Blues», «A Spoonful Blues» og «Down the Dirt Road Blues».","musicians":[],"youtube_id":"_xWqtiFJKfs"},{"year":1929,"title":"Grafton, Wisconsin-øktene (Paramount-studioet)","producer":"Arthur Laibly (Paramount A&R)","label":"Paramount Records","notes":"November–desember 1929 — over tjue nye spor, deriblant tospors-låten «High Water Everywhere», hans skildring av Mississippi-flommen i 1927.","musicians":[],"youtube_id":"Ctt1LDAiZN4"},{"year":1930,"title":"Grafton, Wisconsin-økten (med Son House, Willie Brown & Louise Johnson)","producer":"Arthur Laibly (Paramount A&R)","label":"Paramount Records","notes":"28. mai 1930 — regnes av mange som en av de definerende øktene i den akustiske Delta-bluesæraen.","musicians":[{"name":"Son House","instrument":"Gitar/Vokal"},{"name":"Willie Brown","instrument":"Gitar"},{"name":"Louise Johnson","instrument":"Piano"},{"name":"Son Sims","instrument":"Fiolin"}],"youtube_id":"3o4ol6DmeKc"},{"year":1934,"title":"New York City-øktene (siste innspillinger)","producer":"W.R. Calaway (American Record Corporation / Vocalion)","label":"Vocalion Records","notes":"30.–31. januar og 1. februar 1934 — Pattons siste innspillinger, gjort etter at Calaway løslot ham og Bertha Lee mot kausjon fra et fengsel i Belzoni, Mississippi. Flere spor har Bertha Lees vokal, deriblant «Oh Death».","musicians":[{"name":"Bertha Lee Pate","instrument":"Vokal"}],"youtube_id":"JwC9_ud4Oyo"}]}',
  videos = '[{"kind":"featured","title":"Charley Patton - Pony Blues (1929)","youtube_id":"_xWqtiFJKfs","channel":"Classic Mood Experience","note":"His June 1929 Paramount breakout single, cut at the Gennett/Starr studio in Richmond, Indiana — the record that made him a star across the Delta."},{"kind":"more","title":"Charley Patton - High Water Everywhere (Pts. 1 & 2)","youtube_id":"Ctt1LDAiZN4","channel":"BD Music"},{"kind":"more","title":"Charley Patton - Down the Dirt Road Blues (1929)","youtube_id":"7lHbXhgZwzg","channel":"urjasager"},{"kind":"more","title":"Charley Patton - A Spoonful Blues (Delta Blues) - 1929","youtube_id":"3o4ol6DmeKc","channel":"New Orlean Jazz-Pub"},{"kind":"more","title":"Charley Patton - The Vocalion Recordings - Oh Death with Bertha Lee","youtube_id":"JwC9_ud4Oyo","channel":"Ab Borburgh"},{"kind":"more","title":"Charley Patton – The Father of Delta Blues (1929–1934)","youtube_id":"JS_LYipwmnw","channel":"Vintage Love Records"}]',
