  article_references = '[{"title":"Charley Patton — Wikipedia","url":"https://en.wikipedia.org/wiki/Charley_Patton"},{"title":"Charley Patton Birthplace — Mississippi Blues Trail","url":"https://msbluestrail.org/blues-trail-markers/charley-patton-birthplace"},{"title":"Dockery Farms — Birthplace of the Blues — Mississippi Blues Trail","url":"https://msbluestrail.org/blues-trail-markers/birthplace-of-the-blues"},{"title":"Robert Palmer — Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_Palmer_(American_writer)"},{"title":"Deep Blues: A Musical and Cultural History of the Mississippi Delta (1981) — Robert Palmer","url":"https://www.goodreads.com/en/book/show/269359.Deep_Blues"},{"title":"Gayle Dean Wardlow — Wikipedia","url":"https://en.wikipedia.org/wiki/Gayle_Dean_Wardlow"},{"title":"Chasin'' That Devil''s Music — Gayle Dean Wardlow (Blues Hall of Fame)","url":"https://www.blues.org/blues_hof_inductee/chasin-that-devils-music-by-gayle-dean-wardlow-edited-by-edward-komara/"},{"title":"Dr. David Evans and the Study of the Blues","url":"http://www.internationaldeltabluesproject.com/news1/2016/9/29/dr-david-evans-and-the-study-of-the-blues"}]',
  press_quotes_i18n = '{"en":[{"quote":"One of the most important American musicians of the twentieth century.","author":"Robert Palmer","role":"Music critic, The New York Times; author of Deep Blues (1981)","source_title":"Deep Blues: A Musical and Cultural History of the Mississippi Delta","source_url":"https://www.goodreads.com/en/book/show/269359.Deep_Blues","year":1981},{"quote":"All played the old cheap Stella guitars, across the board.","author":"H.C. Speir","role":"Talent scout who recommended Patton to Paramount Records, on the Delta bluesmen he auditioned","source_title":"What did they play? — Stella Guitars","source_url":"https://stellaguitars.com/about/what-did-they-play/"}],"no":[{"quote":"One of the most important American musicians of the twentieth century.","author":"Robert Palmer","role":"Musikkkritiker, The New York Times; forfatter av Deep Blues (1981)","source_title":"Deep Blues: A Musical and Cultural History of the Mississippi Delta","source_url":"https://www.goodreads.com/en/book/show/269359.Deep_Blues","year":1981},{"quote":"All played the old cheap Stella guitars, across the board.","author":"H.C. Speir","role":"Talentspeideren som anbefalte Patton til Paramount Records, om Delta-bluesmennene han hørte på","source_title":"What did they play? — Stella Guitars","source_url":"https://stellaguitars.com/about/what-did-they-play/"}]}'
